Guard responsibility

AuthGuard canActivate()

Incoming request

Extract Authorization header

Require Bearer scheme

Verify Supabase JWT

Attach authenticated identity

Allow controller execution

Authenticated identity type
// common/types/authenticated-user.ts
export type AuthenticatedUser = {
id: string
email?: string
role?: string
sessionId?: string
}

Guard implementation
// auth/supabase-auth.guard.ts
import {
CanActivate,
ExecutionContext,
Injectable,
UnauthorizedException,
} from '@nestjs/common'
import type { FastifyRequest } from 'fastify'
import { SupabaseAuthService } from './supabase-auth.service'

type AuthenticatedRequest = FastifyRequest & {
user?: {
id: string
email?: string
role?: string
sessionId?: string
}
}

@Injectable()
export class SupabaseAuthGuard implements CanActivate {
constructor(
private readonly auth: SupabaseAuthService,
) {}

async canActivate(
context: ExecutionContext,
): Promise<boolean> {
const request =
context.switchToHttp()
.getRequest<AuthenticatedRequest>()

const token = this.extractBearerToken(request)
const claims = await this.auth.verifyAccessToken(token)

request.user = {
id: claims.sub,
email:
typeof claims.email === 'string'
? claims.email
: undefined,
role:
typeof claims.role === 'string'
? claims.role
: undefined,
sessionId:
typeof claims.session_id === 'string'
? claims.session_id
: undefined,
}

return true
}

private extractBearerToken(
request: FastifyRequest,
): string {
const value = request.headers.authorization
const [scheme, token] = value?.split(' ') ?? []

if (scheme !== 'Bearer' || !token) {
throw new UnauthorizedException(
'Bearer access token required',
)
}

return token
}
}

What the guard does not do
• It does not decide Workspace permissions.

• It does not decide Task ownership.

• It does not decide whether a workflow transition is allowed.

• It does not query Prisma merely to prove the JWT signature.

Authentication creates trusted identity. Authorization and business rules remain separate layers.

